% GENERATED by tools/make_matlab_case.py from cosserat_yeoh_quasistatic.m.
% Solver unchanged; base pose and loads come from CASE_* variables (see run_cases.m).

%% Cosserat rod: rigid insertion + 2 pneumatic soft sections, Yeoh material,
%% quasi-static approximation of the dynamic model
%
% Formulation: Alessi et al., "Rod models in continuum and soft robot control:
% a review" (arXiv 2407.05886v1), Sec. 2.2 and Sec. 3.
%
% ---- Dynamic model (paper Eq. 9 + Eq. 6, inertial frame, net n_{i,a}, m_{i,a}) ----
%   rho*A * dv/dt                        = n'  + n_e
%   rho*I * dw/dt + w x (rho*I*w)        = m'  + r' x n + m_e
%   F_i = F_Yeoh(xi) + Upsilon * dxi/dt          (internal wrench; xi = [kappa; sigma])
%   n = n_i - n_a ,  m = m_i - m_a               (actuation wrench F_a = B_tau*tau, tau = p*A_in)
%
% ---- Quasi-static approximation used here ----
%   Dropped: inertia (dv/dt, dw/dt, w x ...) and viscous term Upsilon*dxi/dt.
%   What remains is   F_Yeoh(xi) + F_a = Lambda_ext ,  i.e.
%       0 = n' + n_e
%       0 = m' + r' x n          (m_e = 0)
%       F_i = F_Yeoh(xi)
%   Time enters ONLY through the inputs p(t) (smooth-step pressure ramp):
%   the robot is assumed to be in equilibrium at every instant, and the
%   equilibria are computed in sequence with warm starts.
%
% ---- Inextensible rod ----
%   Elongation/compression removed: sigma_x = 1 always. Shear (sigma_y,
%   sigma_z) and twist (kappa_x) are kept, linear with G0 = 2*C10.
%   n_x is then a reaction force fixed by equilibrium, not by a constitutive law.
%
% ---- Yeoh bending law ----
%   W = C10 (I1-3) + C20 (I1-3)^2 + C30 (I1-3)^3, incompressible.
%   Fibre at cross-section offset (y,z) has stretch  lambda = 1 + kappa_y*z - kappa_z*y
%   (uniaxial state, I1 = lambda^2 + 2/lambda), nominal stress
%       P(lambda) = (2*lambda - 2/lambda^2) * (C10 + 2 C20 (I1-3) + 3 C30 (I1-3)^2).
%   Bending moment  m = int P(lambda) * (0, z, -y) dA  (integrated over the
%   circular section) gives a scalar law M(k), |kappa_perp| = k, tabulated in
%   makeSection() and inverted by lookup (wrench -> strain).
%
% Conventions: body-frame tangent is x (paper Eq. 20); [angular; linear]
% ordering; base quaternion maps body x -> world +Z.


%% 1) Robot geometry and material ----------------------------------------
robot.Lrigid = 0.080;                    % rigid insertion length [m]
robot.rigidRadius = 4.5e-3;              % display radius [m]
robot.basePosition = [0; 0; 0];          % [m]
if exist('CASE_P','var'), robot.basePosition = CASE_P(:); end
robot.baseQuaternion = [cos(-pi/4); 0; sin(-pi/4); 0];   % body x -> world +Z
if exist('CASE_Q','var'), robot.baseQuaternion = CASE_Q(:); end

% makeSection(L, radius, [C10 C20 C30] [Pa], rho, chamberOffset, chamberRadius, nChambers)
% PLACEHOLDERS: C10 = E/6 for E ~ 0.35 / 0.25 MPa; C20, C30 must come from
% your own material tests (uniaxial tension fit).
sec(1) = makeSection(0.120, 6.0e-3, [58.3e3, 5e3, 0.5e3], 1050, 3.5e-3, 2.0e-3, 3);
sec(2) = makeSection(0.100, 5.5e-3, [41.7e3, 4e3, 0.4e3], 1050, 3.2e-3, 1.8e-3, 3);
if exist('CASE_SEC','var'), for jj = 1:2, sec(jj) = makeSection(sec(jj).L, CASE_SEC(jj,1), sec(jj).yeoh, sec(jj).rho, CASE_SEC(jj,2), CASE_SEC(jj,3), size(sec(jj).d,2)); end, end
if exist('CASE_L','var'), sec(1).L = CASE_L(1); sec(2).L = CASE_L(2); end

%% 2) Final pressure command ---------------------------------------------
% Option A: set gauge pressures [Pa] per chamber directly.
% Option B: request a bend (theta, phi); pressures from the Yeoh moment law
% M(k) (exact for the unloaded, planar-moment balance; loaded shape differs).
pTarget{1} = pressureFromBend(sec(1), deg2rad(35), deg2rad(0));
pTarget{2} = pressureFromBend(sec(2), deg2rad(50), deg2rad(70));
if exist('CASE_BEND','var'), for jj = 1:2, pTarget{jj} = pressureFromBend(sec(jj), CASE_BEND(jj,1), CASE_BEND(jj,2)); end, end

%% 3) Loads, time stepping, numerical settings ---------------------------
loadData.gravity = CASE_G(:);
loadData.tipForce = CASE_F(:);
loadData.tipMoment = [0; 0; 0];           % world frame [N*m]

sim.tEnd = 1.0;                           % [s] pressure ramp duration
sim.nSteps = 8;                           % number of quasi-static steps
sim.t = linspace(0, sim.tEnd, sim.nSteps+1);
smoothStep = @(u) 3*u.^2 - 2*u.^3;        % p(t) = smoothStep(t/tEnd) * pTarget

solver.relTol = 1e-6;
solver.absTol = 1e-8;
solver.pointsPerSection = 81;
solver.verbose = false;

%% 4) Quasi-static simulation over p(t) ----------------------------------
nT = numel(sim.t);
tipPos = zeros(3,nT);
history = cell(1,nT);
guess = [];
for k = 1:nT
    scale = smoothStep(sim.t(k)/sim.tEnd);
    for j = 1:2
        sec(j).p = scale*pTarget{j};
    end
    solution = solveTwoSectionCosserat(robot, sec, loadData, solver, guess);
    guess = solution;                    % warm start next equilibrium
    tipPos(:,k) = solution.r(:,end);
    history{k} = solution;
    fprintf('t = %5.3f s  p-scale = %.3f  tip [mm] = [%8.2f %8.2f %8.2f]  exit %d\n', ...
        sim.t(k), scale, 1e3*tipPos(:,k), solution.exitflag);
end
solution = history{end};

fprintf('\nFinal chamber pressures [kPa]: sec1 = [%s], sec2 = [%s]\n', ...
    num2str(sec(1).p.'/1e3,'%7.2f'), num2str(sec(2).p.'/1e3,'%7.2f'));
fprintf('Tip force residual [N]     = %.3e\n', norm(solution.n(:,end) - loadData.tipForce));
fprintf('Tip moment residual [N*m]  = %.3e\n', norm(solution.m(:,end) - loadData.tipMoment));

i1 = find(solution.sectionId == 1);
i2 = find(solution.sectionId == 2);
i2 = [i2(1)-1, i2];
fprintf('Achieved tangent rotation [deg]: sec1 = %.2f, sec2 = %.2f\n', ...
    tangentRotationDeg(solution.q(:,i1)), tangentRotationDeg(solution.q(:,i2)));
kMax = max(sqrt(sum(solution.xi(2:3,:).^2,1)));
fprintf('Max |kappa_perp| = %.2f 1/m  ->  max fibre strain ~ %.2f %% (sec1 radius)\n', ...
    kMax, 100*kMax*sec(1).radius);
fprintf('  (Yeoh and linear laws differ noticeably only at tens of %% strain)\n');

writematrix(solution.r.', CASE_OUT);
fprintf('CASE %s tip [mm] = [%8.2f %8.2f %8.2f]\n', CASE_OUT, 1e3*solution.r(:,end));

%% Local functions =======================================================
function section = makeSection(L,radius,yeoh,rho,chamberOffset,chamberRadius,nChambers)
    C10 = yeoh(1);
    A  = pi*radius^2;
    Jy = pi*radius^4/4;
    Jx = 2*Jy;                              % polar moment (torsion about tangent x)
    G0 = 2*C10;                             % small-strain shear modulus (incompressible Yeoh)
    E0 = 3*G0;                              % small-strain Young modulus

    section.L = L;  section.radius = radius;  section.rho = rho;  section.A = A;
    section.yeoh = yeoh(:).';
    section.E0 = E0;  section.G0 = G0;
    section.GJx = G0*Jx;                    % twist stiffness (linear)
    section.GA  = G0*A;                     % shear stiffness (linear)
    section.EJ0 = E0*Jy;                    % small-strain bending stiffness (reference only)
    section.xiStar = [0; 0; 0; 1; 0; 0];    % straight, sigma_x = 1 (inextensible)

    % Chambers: local cross-section is the y-z plane
    alpha = 2*pi*(0:nChambers-1)/nChambers;
    section.d   = [zeros(1,nChambers); chamberOffset*cos(alpha); chamberOffset*sin(alpha)];
    section.Ain = pi*chamberRadius^2;
    section.p   = zeros(nChambers,1);
    section.nFixedPoint = 3;                % xi <-> B_tau(xi) implicit coupling

    % Tabulate Yeoh bending law M(k) = int P(1 + k z) z dA over the disk
    nz = 600;
    dz = 2*radius/nz;
    z  = -radius + dz*((1:nz) - 0.5);
    w  = 2*sqrt(radius^2 - z.^2)*dz;        % chord length * dz = dA
    nk = 1500;
    kTab = linspace(0, 0.9/radius, nk);     % lambda > 0 guaranteed
    MTab = zeros(1,nk);
    for i = 1:nk
        lam = 1 + kTab(i)*z;
        MTab(i) = sum(yeohStress(lam,section.yeoh).*z.*w);
    end
    section.kTab = kTab;  section.MTab = MTab;
    % Inverse table on a uniform M grid for fast scalar lookup
    section.dM = MTab(end)/(nk-1);
    MGrid = (0:nk-1)*section.dM;
    section.kGrid = interp1(MTab,kTab,MGrid,'linear');
    section.kGrid(end) = kTab(end);
end

function P = yeohStress(lam,C)
    I1 = lam.^2 + 2./lam;
    dW = C(1) + 2*C(2)*(I1-3) + 3*C(3)*(I1-3).^2;
    P  = (2*lam - 2./lam.^2).*dW;           % nominal uniaxial stress, incompressible
end

function k = curvatureFromMoment(mag,section)
    u = mag/section.dM;
    i = floor(u) + 1;
    if i >= numel(section.kGrid)
        k = section.kGrid(end);             % clamp at table limit (k = 0.9/radius)
        return
    end
    f = u - (i-1);
    k = (1-f)*section.kGrid(i) + f*section.kGrid(i+1);
end

function p = pressureFromBend(section,bendAngle,bendingPlane)
    % Target bending moment from the Yeoh law, M(k); chamber forces give
    % m = sum_i [0; dz_i; -dy_i]*tau_i.  Bend toward azimuth phi (from y toward z):
    %   kappa_y = -k sin(phi),  kappa_z = k cos(phi).
    k = bendAngle/section.L;
    Mk = interp1(section.kTab,section.MTab,k);
    mTarget = Mk*[-sin(bendingPlane); cos(bendingPlane)];   % [m_y; m_z]
    M = [section.d(3,:); -section.d(2,:)];
    tau = pinv(M)*mTarget;
    tau = tau - min(tau);          % uniform offset adds no moment, keeps p >= 0
    p = tau/section.Ain;
end

function Fa = actuationWrench(xi,d,tau)
    % Eqs. (31), (33), (35), fixed chamber offset (d_i' = 0), [moment; force] local
    kappa = xi(1:3);  sigma = xi(4:6);
    Fa = zeros(6,1);
    for i = 1:size(d,2)
        tv = cross(kappa,d(:,i)) + sigma;
        t  = tv/norm(tv);
        Fa = Fa + [cross(d(:,i),t); t]*tau(i);
    end
end

function xi = strainFromState(y,section)
    % Lambda = F_i - F_a (net wrench, local frame).  F_i = Lambda + F_a is
    % inverted through the constitutive law:
    %   twist   kappa_x = m_x / GJx                (linear)
    %   bending [kappa_y; kappa_z] = k(|m_perp|) * m_perp/|m_perp|   (Yeoh table)
    %   shear   sigma_y,z = n_y,z / GA            (linear)
    %   stretch sigma_x = 1                       (inextensible)
    R   = quatToRotmLocal(y(4:7));
    Lam = [R.'*y(11:13); R.'*y(8:10)];
    tau = section.p(:)*section.Ain;
    xi  = section.xiStar;
    for it = 1:section.nFixedPoint
        Fi  = Lam + actuationWrench(xi,section.d,tau);
        mp  = Fi(2:3);
        mag = norm(mp);
        if mag > 0
            kp = curvatureFromMoment(mag,section)*mp/mag;
        else
            kp = [0;0];
        end
        xi = [Fi(1)/section.GJx; kp; 1; Fi(5)/section.GA; Fi(6)/section.GA];
    end
end

function sol = solveTwoSectionCosserat(robot,sec,loadData,solver,guess)
    q0 = robot.baseQuaternion(:)/norm(robot.baseQuaternion);
    R0 = quatToRotmLocal(q0);
    rSoft0 = robot.basePosition(:) + R0*[robot.Lrigid;0;0];

    fDist1 = sec(1).rho*sec(1).A*loadData.gravity(:);
    fDist2 = sec(2).rho*sec(2).A*loadData.gravity(:);
    totalDistributedForce = fDist1*sec(1).L + fDist2*sec(2).L;
    forceScale = max([norm(loadData.tipForce), norm(totalDistributedForce), 1e-2]);
    momentScale = max([norm(loadData.tipMoment), ...
                       forceScale*(sec(1).L+sec(2).L), 1e-3]);

    if isempty(guess)
        nGuess = loadData.tipForce(:) + totalDistributedForce;
        lever  = R0*[sec(1).L+sec(2).L;0;0];
        mGuess = loadData.tipMoment(:) + cross(lever,loadData.tipForce(:));
    else                                    % warm start from previous equilibrium
        nGuess = guess.initialInternalForce;
        mGuess = guess.initialInternalMoment;
    end
    x0 = [nGuess/forceScale; mGuess/momentScale];

    residual = @(x) shootingResidual(x,rSoft0,q0,sec,loadData,solver, ...
                                      forceScale,momentScale);

    usedFsolve = false;
    if exist('fsolve','file') == 2
        try
            options = optimoptions('fsolve','Display','none', ...
                'FunctionTolerance',1e-9,'StepTolerance',1e-9, ...
                'MaxFunctionEvaluations',800);
            [xStar,~,exitflag] = fsolve(residual,x0,options);
            solverName = 'fsolve';
            usedFsolve = true;
        catch solverError
            warning('fsolve was unavailable (%s). Using fminsearch.', ...
                    solverError.message);
        end
    end
    if ~usedFsolve
        objective = @(x) sum(residual(x).^2);
        options = optimset('Display','off','TolX',1e-8,'TolFun',1e-12, ...
                           'MaxFunEvals',3000,'MaxIter',1200);
        [xStar,~,exitflag] = fminsearch(objective,x0,options);
        solverName = 'fminsearch';
    end

    n0 = forceScale*xStar(1:3);
    m0 = momentScale*xStar(4:6);
    y0 = [rSoft0; q0; n0; m0];
    [s,y,sectionId] = integrateAllSections(y0,sec,loadData,solver, ...
                                           solver.pointsPerSection);

    sol.s = s.';
    sol.r = y(:,1:3).';
    sol.q = y(:,4:7).';
    sol.n = y(:,8:10).';
    sol.m = y(:,11:13).';
    sol.sectionId = sectionId.';
    sol.softBasePosition = rSoft0;
    sol.initialInternalForce = n0;
    sol.initialInternalMoment = m0;
    sol.exitflag = exitflag;

    sol.xi = zeros(6,numel(s));
    for j = 1:numel(s)
        sol.xi(:,j) = strainFromState(y(j,:).',sec(sectionId(j)));
    end

    if exitflag <= 0
        warning('The shooting solver may not have converged (exit flag %d).', ...
                exitflag);
    end
    if solver.verbose
        fprintf('Shooting solver: %s, exit flag: %d\n',solverName,exitflag);
    end
end

function res = shootingResidual(x,r0,q0,sec,loadData,solver,Fscale,Mscale)
    n0 = Fscale*x(1:3);
    m0 = Mscale*x(4:6);
    y0 = [r0; q0; n0; m0];
    [~,y] = integrateAllSections(y0,sec,loadData,solver,0);
    yTip = y(end,:).';
    res = [(yTip(8:10)-loadData.tipForce(:))/Fscale; ...
           (yTip(11:13)-loadData.tipMoment(:))/Mscale];
end

function [sAll,yAll,sectionId] = integrateAllSections(y0,sec,loadData,solver,nPts)
    odeOptions = odeset('RelTol',solver.relTol,'AbsTol',solver.absTol);
    sAll = []; yAll = []; sectionId = [];
    sOffset = 0;
    for k = 1:numel(sec)
        if nPts > 1
            sSpan = linspace(0,sec(k).L,nPts);
        else
            sSpan = [0,sec(k).L];
        end
        odeFun = @(s,y) cosseratODE(s,y,sec(k),loadData);
        [sLocal,yLocal] = ode45(odeFun,sSpan,y0,odeOptions);

        first = 1 + (k>1);
        sAll = [sAll; sOffset+sLocal(first:end)]; %#ok<AGROW>
        yAll = [yAll; yLocal(first:end,:)]; %#ok<AGROW>
        sectionId = [sectionId; k*ones(numel(sLocal(first:end)),1)]; %#ok<AGROW>

        y0 = yLocal(end,:).';
        y0(4:7) = y0(4:7)/norm(y0(4:7));
        sOffset = sOffset + sec(k).L;
    end
end

function dyds = cosseratODE(~,y,section,loadData)
    % Quasi-static Eq. (9): 0 = n' + n_e ;  0 = m' + r' x n   (m_e = 0)
    q = y(4:7)/norm(y(4:7));
    n = y(8:10);
    R = quatToRotmLocal(q);

    xi = strainFromState(y,section);
    kappa = xi(1:3);
    sigma = xi(4:6);                          % sigma_x = 1 (inextensible)

    rPrime = R*sigma;                         % g' = g*xi_hat
    qPrime = 0.5*quatMultiply(q,[0;kappa]);
    ne = section.rho*section.A*loadData.gravity(:);
    nPrime = -ne;
    mPrime = -cross(rPrime,n);

    dyds = [rPrime; qPrime; nPrime; mPrime];
end

function ang = tangentRotationDeg(q)
    t0 = quatToRotmLocal(q(:,1))*[1;0;0];
    t1 = quatToRotmLocal(q(:,end))*[1;0;0];
    ang = acosd(max(-1,min(1,dot(t0,t1))));
end

function qp = quatMultiply(q,p)
    qw=q(1); qv=q(2:4); pw=p(1); pv=p(2:4);
    qp = [qw*pw-dot(qv,pv); qw*pv+pw*qv+cross(qv,pv)];
end

function R = quatToRotmLocal(q)
    q = q(:)/norm(q);
    w=q(1); x=q(2); y=q(3); z=q(4);
    R = [1-2*(y*y+z*z), 2*(x*y-z*w),   2*(x*z+y*w); ...
         2*(x*y+z*w),   1-2*(x*x+z*z), 2*(y*z-x*w); ...
         2*(x*z-y*w),   2*(y*z+x*w),   1-2*(x*x+y*y)];
end

function drawTube(ax,r,q,radius,colorValue,faceAlpha)
    nCirc = 64;
    theta = linspace(0,2*pi,nCirc);
    X = zeros(nCirc,size(r,2));
    Y = X; Z = X;
    for j = 1:size(r,2)
        R = quatToRotmLocal(q(:,j));
        ring = r(:,j) + R*[zeros(1,nCirc); radius*cos(theta); radius*sin(theta)];
        X(:,j)=ring(1,:).'; Y(:,j)=ring(2,:).'; Z(:,j)=ring(3,:).';
    end
    surf(ax,X,Y,Z,'FaceColor',colorValue,'EdgeColor','none','FaceAlpha',faceAlpha);
end

function drawFrames(ax,r,q,scale)
    frameColors = eye(3);
    for j = 1:size(r,2)
        R = quatToRotmLocal(q(:,j));
        for k = 1:3
            p = r(:,j) + scale*R(:,k);
            plot3(ax,[r(1,j),p(1)],[r(2,j),p(2)],[r(3,j),p(3)], ...
                '-','Color',frameColors(k,:),'LineWidth',1.0,'HandleVisibility','off');
        end
    end
end
